import time

const (
    num_priorities = 6
)

type EventKey = string

type EventListener = fn(data ?data_ptr)

type data_ptr = ?

struct EventEmitter {
    mut sync.RwMutex
    events map[EventKey][]EventListener
}

fn new_emitter() EventEmitter {
    return EventEmitter{ events: {} }
}

fn (mut e EventEmitter) subscribe(event string, listener EventListener) {
    e.mut.lock()
    defer e.mut.unlock()

    key := event

    if e.events[key].len == 0 {
        e.events[key] = []EventListener{}
    }

    e.events[key] << listener
}

fn (e EventEmitter) emit(event string, data ?data_ptr, priority int) {
    e.mut.lock_shared()
    defer e.mut.unlock_shared()

    key := event
    listeners := e.events[key] or { [] }
    priority_queue.add(priority, fn { 
        for listener in listeners {
            listener(data)
        }
    })
}

struct PriorityQueue {
    queues [num_priorities][]fn()
}

fn new_priority_queue() PriorityQueue {
    mut pq := PriorityQueue{}
    for i := 0; i < num_priorities; i++ {
        pq.queues[i] = []fn()
    }
    return pq
}

fn (mut pq PriorityQueue) add(priority int, task fn()) {
    if priority < 0 {
        priority = 0
    } else if priority >= num_priorities {
        priority = num_priorities - 1
    }
    pq.queues[priority] << task
}

static mut priority_queue := new_priority_queue()

fn listener1(data ?data_ptr) {
    if let Some(str) = data.? as string {
        println("Listener1: " + str)
    }
}

fn listener2(data ?data_ptr) {
    if let Some(str) = data.? as string {
        println("Listener2: " + str)
    }
}

fn main() {
    mut emitter := new_emitter()

    emitter.subscribe("event1", listener1)
    emitter.subscribe("event1", listener2)

    mut hello1 := "Hello, world! Priority 1"
    emitter.emit("event1", &hello1, 1)
    mut hello2 := "Hello, world! Priority 2"
    emitter.emit("event1", &hello2, 2)

    time.sleep(1 * time.second)
}

