import java.util.List;

public class Result {
    public static double interpolate_by_newton(List<Double> x_axis, List<Double> y_axis, double x0) {
        int n = x_axis.size();
        double[] divDiff = new double[n];
        double result = y_axis.get(0);

        for (int i = 0; i < n; i++) {
            divDiff[i] = y_axis.get(i);
        }
        for (int i = 1; i < n; i++) {
            for (int j = n - 1; j >= i; j--) {
                divDiff[j] = (divDiff[j] - divDiff[j - 1]) / (x_axis.get(j) - x_axis.get(j - i));
            }
            result += divDiff[i] * calculateCoefficients(x0, x_axis, i);
        }
        return result;
    }
    static double calculateCoefficients(double x, List<Double> arr, int n) {
        double result = 1;
        for (int i = 0; i < n; i++) {
            result *= (x - arr.get(i));
        }
