reward = -0.1;
}

// Train the neural network on the input-output pair
double[] targetOutputs = new double[NUM_OUTPUTS];
targetOutputs[action] = 1;
neuralNetwork.train(inputs, targetOutputs, reward);
}
}
}

private void resetGrid() {
