display: inline-block;
}

.dropbtn {
background-color: #16a085;
color: white;
padding: 10px 20px;
font-size: 16px;
border: none;
cursor: pointer;
border-radius: 5px;
}

.dropdown-content {
display: none;
position: absolute;
z-index: 1;
background-color: #f39c12;
}

.dropdown-content a {
color: #fff;
padding: 12px 16px;
text-decoration: none;
display: block;
}

.dropdown:hover .dropdown-content {
display: block;
}

.main {
height: 200px;
width: auto;
margin-top: 20px;
}

.footer {
background-color: #16a085;
color: white;
text-align: center;
padding: 10px;
position: absolute;
bottom: 0;
left: 0;
right: 0;
}

